public static ISMBatchableTelemetryWorkingMemory construct()
{
    ISMBatchableTelemetryWorkingMemory workingMemory = new ISMBatchableTelemetryWorkingMemory();
    return workingMemory;
}

protected void new()
{
    super();

    this.eventId = ISMTelemetryEventIds::ISMEvent;
}

/// <summary>
/// Method signature provides the contract class to the SysOperation framework to
/// dynamically generate the configuration dialog.
/// </summary>
/// <param name = "_contract">Parameter to define the contract class</param>
/// <remarks>
/// Method is not called, only defines the contract class via its signature.
/// </remarks>
public void defineWorkingMemoryContract(ISMBatchableTelemetryWorkingMemoryContract _contract)
{
}

public void fillConfigurationContract(SysPackable _contract)
{
    ISMBatchableTelemetryWorkingMemoryContract contract;
    if (_contract && _contract is ISMBatchableTelemetryWorkingMemoryContract)
    {
        contract = _contract as ISMBatchableTelemetryWorkingMemoryContract;
        if (telemetryConfig != null)
        {
            contract.unpack(telemetryConfig.pack());
        }
    }
}

protected void initializeConfiguration(SysPackable _configuration)
{
    ISMBatchableTelemetryWorkingMemoryContract contract = 
        _configuration as ISMBatchableTelemetryWorkingMemoryContract;
    if (contract)
    {
        contract.parmMetricName('Remaining Memory MB');
        contract.parmLogAsMetric(true);
        contract.parmLogAsEvent(false);
    }
}

protected ClassName metricName()
{
    ISMBatchableTelemetryWorkingMemoryContract contract = this.telemetryConfig;
    return contract.parmMetricName();
}
